llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C47"],
      "claim": "Safinamide absolute oral bioavailability was 95.0% in healthy subjects after a 50 mg IR tablet versus IV, demonstrating near-complete absorption and low first-pass loss; this high-F phenotype transfers strongly to the query's small amide-containing neutral scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C70"],
      "claim": "Isoniazid, a small polar heteroaromatic drug, had 93% absolute oral bioavailability in fasting adult TB patients; its high oral absorption supports high F for the similarly small nitroimidazole acetamide query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "Atazanavir absolute oral bioavailability was 68% (57–80%) in humans, well above the 20% threshold; despite larger size, its high transfer score supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Fenspiride absolute bioavailability was 90% in healthy volunteers, indicating essentially complete oral absorption; supports high F for the amide-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C73"],
      "claim": "Quinapril absolute bioavailability was 51.7% in healthy participants, above threshold; supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Vorinostat absolute oral bioavailability was approximately 43% in fasting humans, above threshold; its amide-containing structure supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Ampicillin absolute bioavailability was 55.3% in subjects, above threshold; supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Pethidine absolute oral bioavailability ranged 47–73% in healthy men, above threshold; supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "One labetalol record reports 18% oral bioavailability, below threshold, but this is a single borderline value among labetalol records ranging 20–38%; it provides only weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a small neutral amide with favorable physicochemical properties. Multiple high-transfer analogues with absolute oral bioavailability values of 43–95% consistently support F≥20%; the only sub-20 value is a single borderline labetalol record (18%) that is outweighed by the strong high-F evidence. Prediction: high.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule itself; all evidence is from analogues.",
    "The single low-F labetalol record is borderline and variable, and no low-F analogue with a nitroimidazole core is available.",
    "Potential first-pass metabolism specific to the 2-nitroimidazole moiety is not directly covered by the analogue set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

